SELECT md.chembl_id, md.pref_name, cs.canonical_smiles, di.efo_id AS indication_curie, di.efo_term AS indication_label, di.max_phase_for_ind FROM molecule_dictionary md JOIN drug_indication di ON md.molregno = di.molregno JOIN compound_structures cs ON cs.molregno = md.molregno WHERE md.max_phase = 4 AND (di.efo_term LIKE '%prostate cancer%' OR di.mesh_heading LIKE '%Prostate%') ORDER BY md.chembl_id, md.pref_name, cs.canonical_smiles, indication_curie, indication_label, di.max_phase_for_ind
